function matchRecipeFromPrompt(prompt = "") {
  const lower = prompt.toLowerCase();
  for (const [id, data] of Object.entries(RECIPE_CATALOG)) {
    for (const alias of data.aliases) {
      if (lower.includes(alias)) {
        return { id, ...data };
      }
    }
  }
  return null;
}
